const rnd=(a,b)=>a+Math.random()*(b-a);
let W_=W(),H_=H();
const dust=[];
for(let i=0;i<90;i++){
  dust.push({
    x:rnd(0,W_),
    y:rnd(0,H_),
    r:rnd(0.6,2.2),
    spd:rnd(0.08,0.3),
    drift:rnd(-0.15,0.15),
    phase:rnd(0,Math.PI*2),
    speed2:rnd(0.004,0.012),
    zone: Math.random()<0.5?'top':'bottom'
  });
}
const threads=[];
for(let i=0;i<5;i++){
  threads.push({
    x:rnd(W_*0.1,W_*0.3)+ (i%2===0?0:W_*0.5),
    baseY: i<3? rnd(H_*0.06,H_*0.18) : rnd(H_*0.82,H_*0.94),
    len:rnd(40,90),
    phase:rnd(0,Math.PI*2),
    speed:rnd(0.3,0.6)
  });
}
let t=0;
function frame(){
  t+=0.016;
  W_=W(); H_=H();
  ctx.clearRect(0,0,W_,H_);
  const midY=H_*0.5;
  const safeTop=H_*0.32, safeBot=H_*0.68;

  // мягкие золотые блики сверху/снизу, избегая центра
  for(const d of dust){
    d.y -= d.spd;
    d.x += Math.sin(t*d.speed2*10+d.phase)*d.drift;
    if(d.y<-10){ d.y=H_+10; d.x=rnd(0,W_); }
    // затухание в центре
    let alpha=1;
    if(d.y>safeTop && d.y<safeBot){
      const distCenter=Math.abs(d.y-midY)/(midY-safeTop);
      alpha=Math.max(0,1-distCenter)*0.15;
    } else {
      alpha=0.55;
    }
    const flick=0.6+0.4*Math.sin(t*2+d.phase);
    ctx.beginPath();
    ctx.fillStyle = PALETTE[1];
    ctx.globalAlpha = alpha*flick*0.8;
    ctx.arc(d.x,d.y,d.r,0,Math.PI*2);
    ctx.fill();
  }
  ctx.globalAlpha=1;

  // тонкие покачивающиеся нити (как подвес игрушки)
  for(const th of threads){
    const sway = Math.sin(t*th.speed+th.phase)*8;
    const x0=th.x+sway;
    const y0=th.baseY;
    const x1=th.x+sway*1.6;
    const y1=th.baseY + (th.baseY<midY? th.len : -th.len);
    const grad=ctx.createLinearGradient(x0,y0,x1,y1);
    grad.addColorStop(0, PALETTE[1]+'cc');
    grad.addColorStop(1, PALETTE[1]+'00');
    ctx.strokeStyle=grad;
    ctx.lineWidth=1.1;
    ctx.beginPath();
    ctx.moveTo(x0,y0);
    ctx.quadraticCurveTo((x0+x1)/2+Math.sin(t*th.speed*1.3)*5, (y0+y1)/2, x1,y1);
    ctx.stroke();

    // маленький светящийся узелок-орешек на конце нити
    const glow=ctx.createRadialGradient(x1,y1,0,x1,y1,10);
    glow.addColorStop(0, PALETTE[2]+'aa');
    glow.addColorStop(1, PALETTE[2]+'00');
    ctx.fillStyle=glow;
    ctx.beginPath();
    ctx.arc(x1,y1,10,0,Math.PI*2);
    ctx.fill();
  }

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
